-- ORYN initial schema.
-- Conventions: UUID primary keys (generated by the application, UUIDv7 where ordering matters),
-- timestamptz everywhere, soft deletion via deleted_at on user-facing aggregates,
-- enumerations stored as text with CHECK constraints (mirrors oryn-domain).
-- JSONB is used only for evidence blobs, analysis snapshots and provider-specific config.

CREATE EXTENSION IF NOT EXISTS vector;
CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- ───────────────────────── Identity ─────────────────────────
CREATE TABLE users (
    id              uuid PRIMARY KEY,
    email           text NOT NULL,
    name            text NOT NULL,
    password_hash   text,
    oidc_issuer     text,
    oidc_subject    text,
    is_instance_admin boolean NOT NULL DEFAULT false,
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now(),
    deleted_at      timestamptz
);
CREATE UNIQUE INDEX users_email_uq ON users (lower(email)) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX users_oidc_uq ON users (oidc_issuer, oidc_subject) WHERE oidc_subject IS NOT NULL;

CREATE TABLE sessions (
    id            uuid PRIMARY KEY,
    user_id       uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_hash    text NOT NULL UNIQUE,
    user_agent    text,
    ip            text,
    created_at    timestamptz NOT NULL DEFAULT now(),
    last_seen_at  timestamptz NOT NULL DEFAULT now(),
    expires_at    timestamptz NOT NULL
);
CREATE INDEX sessions_user_idx ON sessions (user_id);

CREATE TABLE oidc_states (
    state         text PRIMARY KEY,
    nonce         text NOT NULL,
    pkce_verifier text NOT NULL,
    redirect_to   text,
    created_at    timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE workspaces (
    id          uuid PRIMARY KEY,
    name        text NOT NULL,
    slug        text NOT NULL,
    require_approval boolean NOT NULL DEFAULT true,
    created_by  uuid REFERENCES users(id),
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now(),
    deleted_at  timestamptz
);
CREATE UNIQUE INDEX workspaces_slug_uq ON workspaces (slug) WHERE deleted_at IS NULL;

CREATE TABLE roles (
    name        text PRIMARY KEY CHECK (name IN ('owner','admin','engineer','viewer')),
    rank        int NOT NULL,
    description text NOT NULL
);

CREATE TABLE permissions (
    name        text PRIMARY KEY,
    description text NOT NULL
);

CREATE TABLE role_permissions (
    role        text NOT NULL REFERENCES roles(name),
    permission  text NOT NULL REFERENCES permissions(name),
    PRIMARY KEY (role, permission)
);

CREATE TABLE workspace_members (
    workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    user_id      uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    role         text NOT NULL REFERENCES roles(name),
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, user_id)
);
CREATE INDEX workspace_members_user_idx ON workspace_members (user_id);

CREATE TABLE teams (
    id           uuid PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    name         text NOT NULL,
    description  text,
    created_at   timestamptz NOT NULL DEFAULT now(),
    UNIQUE (workspace_id, name)
);

CREATE TABLE team_members (
    team_id  uuid NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
    user_id  uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    PRIMARY KEY (team_id, user_id)
);

CREATE TABLE api_tokens (
    id           uuid PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    user_id      uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    name         text NOT NULL,
    token_hash   text NOT NULL UNIQUE,
    role         text NOT NULL REFERENCES roles(name),
    created_at   timestamptz NOT NULL DEFAULT now(),
    last_used_at timestamptz,
    expires_at   timestamptz,
    revoked_at   timestamptz
);

-- ───────────────────────── Projects ─────────────────────────
CREATE TABLE projects (
    id           uuid PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    name         text NOT NULL,
    slug         text NOT NULL,
    description  text,
    visibility   text NOT NULL DEFAULT 'workspace' CHECK (visibility IN ('workspace','restricted')),
    color        text NOT NULL DEFAULT 'thu',
    created_by   uuid REFERENCES users(id),
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now(),
    deleted_at   timestamptz
);
CREATE UNIQUE INDEX projects_slug_uq ON projects (workspace_id, slug) WHERE deleted_at IS NULL;

CREATE TABLE project_permissions (
    id         uuid PRIMARY KEY,
    project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    user_id    uuid REFERENCES users(id) ON DELETE CASCADE,
    team_id    uuid REFERENCES teams(id) ON DELETE CASCADE,
    role       text NOT NULL REFERENCES roles(name),
    created_at timestamptz NOT NULL DEFAULT now(),
    CHECK ((user_id IS NULL) <> (team_id IS NULL))
);
CREATE INDEX project_permissions_project_idx ON project_permissions (project_id);

CREATE TABLE repository_connections (
    id              uuid PRIMARY KEY,
    workspace_id    uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    kind            text NOT NULL CHECK (kind IN ('github','gitlab')),
    name            text NOT NULL,
    base_url        text NOT NULL,
    token_encrypted text,
    created_by      uuid REFERENCES users(id),
    created_at      timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE repositories (
    id              uuid PRIMARY KEY,
    project_id      uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    connection_id   uuid REFERENCES repository_connections(id) ON DELETE SET NULL,
    source          text NOT NULL CHECK (source IN ('github','gitlab','git','zip','local')),
    url             text,
    default_branch  text,
    local_path      text NOT NULL,
    last_commit     text,
    status          text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','importing','ready','analyzing','failed')),
    error           text,
    size_bytes      bigint,
    file_count      int,
    last_analyzed_at timestamptz,
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX repositories_project_idx ON repositories (project_id);

CREATE TABLE application_contexts (
    id             uuid PRIMARY KEY,
    project_id     uuid NOT NULL UNIQUE REFERENCES projects(id) ON DELETE CASCADE,
    repository_id  uuid REFERENCES repositories(id) ON DELETE SET NULL,
    version        int NOT NULL DEFAULT 1,
    summary        text NOT NULL DEFAULT '',
    -- Analysis snapshot (JSONB: heterogeneous, read whole, never filtered in SQL).
    analysis       jsonb NOT NULL DEFAULT '{}'::jsonb,
    -- path -> sha256 for incremental re-analysis.
    file_hashes    jsonb NOT NULL DEFAULT '{}'::jsonb,
    commit_sha     text,
    analyzed_at    timestamptz NOT NULL DEFAULT now(),
    files_changed_last_run int NOT NULL DEFAULT 0
);

CREATE TABLE application_modules (
    id           uuid PRIMARY KEY,
    project_id   uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    name         text NOT NULL,
    path_prefix  text NOT NULL,
    kind         text NOT NULL DEFAULT 'module',
    description  text,
    file_count   int NOT NULL DEFAULT 0,
    created_at   timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, path_prefix)
);

CREATE TABLE context_chunks (
    id          uuid PRIMARY KEY,
    project_id  uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    source_path text NOT NULL,
    content     text NOT NULL,
    tsv         tsvector GENERATED ALWAYS AS (to_tsvector('english', content)) STORED,
    embedding   vector,
    created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX context_chunks_project_idx ON context_chunks (project_id);
CREATE INDEX context_chunks_tsv_idx ON context_chunks USING gin (tsv);

CREATE TABLE requirements (
    id          uuid PRIMARY KEY,
    project_id  uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    key         text NOT NULL,
    title       text NOT NULL,
    body        text NOT NULL DEFAULT '',
    kind        text NOT NULL DEFAULT 'requirement' CHECK (kind IN ('requirement','user_story','acceptance_criteria','document','api_spec')),
    source      text NOT NULL DEFAULT 'manual',
    parent_id   uuid REFERENCES requirements(id) ON DELETE CASCADE,
    module_id   uuid REFERENCES application_modules(id) ON DELETE SET NULL,
    priority    text NOT NULL DEFAULT 'medium' CHECK (priority IN ('low','medium','high','critical')),
    embedding   vector,
    created_by  uuid REFERENCES users(id),
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now(),
    deleted_at  timestamptz
);
CREATE UNIQUE INDEX requirements_key_uq ON requirements (project_id, key) WHERE deleted_at IS NULL;

-- ───────────────────────── Testing ─────────────────────────
CREATE TABLE test_plans (
    id            uuid PRIMARY KEY,
    project_id    uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title         text NOT NULL,
    objective     text NOT NULL DEFAULT '',
    input         text NOT NULL DEFAULT '',
    status        text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','approved','rejected')),
    source        text NOT NULL CHECK (source IN ('ai','heuristic','manual')),
    rationale     text NOT NULL DEFAULT '',
    risk_analysis jsonb NOT NULL DEFAULT '[]'::jsonb,
    coverage_gaps jsonb NOT NULL DEFAULT '[]'::jsonb,
    ai_request_id uuid,
    created_by    uuid REFERENCES users(id),
    approved_by   uuid REFERENCES users(id),
    approved_at   timestamptz,
    created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX test_plans_project_idx ON test_plans (project_id, created_at DESC);

CREATE TABLE test_suites (
    id             uuid PRIMARY KEY,
    project_id     uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    name           text NOT NULL,
    description    text NOT NULL DEFAULT '',
    path           text,
    feature_source text NOT NULL,
    tags           text[] NOT NULL DEFAULT '{}',
    parse_error    text,
    created_by     uuid REFERENCES users(id),
    created_at     timestamptz NOT NULL DEFAULT now(),
    updated_at     timestamptz NOT NULL DEFAULT now(),
    deleted_at     timestamptz
);
CREATE INDEX test_suites_project_idx ON test_suites (project_id) WHERE deleted_at IS NULL;

CREATE TABLE test_scenarios (
    id            uuid PRIMARY KEY,
    suite_id      uuid NOT NULL REFERENCES test_suites(id) ON DELETE CASCADE,
    project_id    uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    name          text NOT NULL,
    tags          text[] NOT NULL DEFAULT '{}',
    kind          text NOT NULL CHECK (kind IN ('browser','api','mixed')),
    status        text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','approved','archived')),
    origin        text NOT NULL DEFAULT 'manual' CHECK (origin IN ('manual','ai','heuristic','recording','import')),
    line          int NOT NULL DEFAULT 0,
    outline       text,
    example_index int,
    executable    boolean NOT NULL DEFAULT true,
    diagnostics   jsonb NOT NULL DEFAULT '[]'::jsonb,
    position      int NOT NULL DEFAULT 0,
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now(),
    deleted_at    timestamptz
);
CREATE INDEX test_scenarios_suite_idx ON test_scenarios (suite_id) WHERE deleted_at IS NULL;
CREATE INDEX test_scenarios_project_idx ON test_scenarios (project_id) WHERE deleted_at IS NULL;

CREATE TABLE test_plan_items (
    id              uuid PRIMARY KEY,
    plan_id         uuid NOT NULL REFERENCES test_plans(id) ON DELETE CASCADE,
    position        int NOT NULL,
    title           text NOT NULL,
    category        text NOT NULL CHECK (category IN ('functional','negative','boundary','edge_case','regression','integration','security')),
    priority        text NOT NULL DEFAULT 'medium' CHECK (priority IN ('low','medium','high','critical')),
    risk            text NOT NULL DEFAULT '',
    rationale       text NOT NULL DEFAULT '',
    requirement_keys text[] NOT NULL DEFAULT '{}',
    gherkin         text NOT NULL,
    executable      boolean NOT NULL DEFAULT false,
    diagnostics     jsonb NOT NULL DEFAULT '[]'::jsonb,
    status          text NOT NULL DEFAULT 'proposed' CHECK (status IN ('proposed','accepted','rejected')),
    scenario_id     uuid REFERENCES test_scenarios(id) ON DELETE SET NULL
);
CREATE INDEX test_plan_items_plan_idx ON test_plan_items (plan_id, position);

CREATE TABLE test_steps (
    id           uuid PRIMARY KEY,
    scenario_id  uuid NOT NULL REFERENCES test_scenarios(id) ON DELETE CASCADE,
    position     int NOT NULL,
    keyword      text NOT NULL,
    text         text NOT NULL,
    step         jsonb NOT NULL,
    UNIQUE (scenario_id, position)
);

CREATE TABLE step_definitions (
    id          uuid PRIMARY KEY,
    project_id  uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    phrase      text NOT NULL,
    description text NOT NULL DEFAULT '',
    body        text NOT NULL,
    created_by  uuid REFERENCES users(id),
    created_at  timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, phrase)
);

CREATE TABLE requirement_links (
    requirement_id uuid NOT NULL REFERENCES requirements(id) ON DELETE CASCADE,
    scenario_id    uuid NOT NULL REFERENCES test_scenarios(id) ON DELETE CASCADE,
    source         text NOT NULL DEFAULT 'manual' CHECK (source IN ('manual','tag','ai','plan')),
    created_at     timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (requirement_id, scenario_id)
);
CREATE INDEX requirement_links_scenario_idx ON requirement_links (scenario_id);

CREATE TABLE test_data (
    id          uuid PRIMARY KEY,
    project_id  uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    name        text NOT NULL,
    description text NOT NULL DEFAULT '',
    -- Key/value data made available to scenarios as {{name.key}} variables.
    data        jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, name)
);

CREATE TABLE test_environments (
    id             uuid PRIMARY KEY,
    project_id     uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    name           text NOT NULL,
    base_url       text,
    api_base_url   text,
    allowed_hosts  text[] NOT NULL DEFAULT '{}',
    variables      jsonb NOT NULL DEFAULT '{}'::jsonb,
    -- name -> AES-GCM sealed value; never returned by the API.
    secrets        jsonb NOT NULL DEFAULT '{}'::jsonb,
    is_default     boolean NOT NULL DEFAULT false,
    created_at     timestamptz NOT NULL DEFAULT now(),
    updated_at     timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, name)
);

-- ───────────────────────── Execution ─────────────────────────
CREATE TABLE execution_workers (
    id                uuid PRIMARY KEY,
    workspace_id      uuid REFERENCES workspaces(id) ON DELETE CASCADE,
    name              text NOT NULL,
    token_hash        text NOT NULL UNIQUE,
    status            text NOT NULL DEFAULT 'online' CHECK (status IN ('online','offline','draining','revoked')),
    version           text,
    hostname          text,
    os                text,
    concurrency       int NOT NULL DEFAULT 1,
    labels            text[] NOT NULL DEFAULT '{}',
    active_jobs       int NOT NULL DEFAULT 0,
    last_heartbeat_at timestamptz,
    registered_at     timestamptz NOT NULL DEFAULT now(),
    revoked_at        timestamptz
);

CREATE TABLE worker_capabilities (
    worker_id  uuid NOT NULL REFERENCES execution_workers(id) ON DELETE CASCADE,
    capability text NOT NULL,
    version    text,
    available  boolean NOT NULL DEFAULT true,
    PRIMARY KEY (worker_id, capability)
);

CREATE TABLE test_executions (
    id             uuid PRIMARY KEY,
    workspace_id   uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    project_id     uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    environment_id uuid REFERENCES test_environments(id) ON DELETE SET NULL,
    environment_name text NOT NULL,
    suite_id       uuid REFERENCES test_suites(id) ON DELETE SET NULL,
    title          text NOT NULL,
    status         text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','running','passed','failed','error','cancelled')),
    trigger        text NOT NULL DEFAULT 'manual' CHECK (trigger IN ('manual','ci','api','rerun','schedule','regression')),
    browser        text NOT NULL DEFAULT 'chromium' CHECK (browser IN ('chromium','firefox','webkit')),
    rerun_of       uuid REFERENCES test_executions(id) ON DELETE SET NULL,
    commit_sha     text,
    branch         text,
    triggered_by   uuid REFERENCES users(id),
    total          int NOT NULL DEFAULT 0,
    passed         int NOT NULL DEFAULT 0,
    failed         int NOT NULL DEFAULT 0,
    errored        int NOT NULL DEFAULT 0,
    cancelled      int NOT NULL DEFAULT 0,
    created_at     timestamptz NOT NULL DEFAULT now(),
    started_at     timestamptz,
    finished_at    timestamptz,
    duration_ms    bigint
);
CREATE INDEX test_executions_project_idx ON test_executions (project_id, created_at DESC);
CREATE INDEX test_executions_ws_idx ON test_executions (workspace_id, created_at DESC);
CREATE INDEX test_executions_status_idx ON test_executions (status) WHERE status IN ('queued','running');

CREATE TABLE execution_jobs (
    id             uuid PRIMARY KEY,
    execution_id   uuid NOT NULL REFERENCES test_executions(id) ON DELETE CASCADE,
    workspace_id   uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    project_id     uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    scenario_id    uuid REFERENCES test_scenarios(id) ON DELETE SET NULL,
    scenario_name  text NOT NULL,
    kind           text NOT NULL CHECK (kind IN ('browser','api','mixed')),
    status         text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','claimed','running','passed','failed','error','cancelled','timed_out')),
    attempt        int NOT NULL DEFAULT 1,
    max_attempts   int NOT NULL DEFAULT 2,
    retry_on_failure boolean NOT NULL DEFAULT false,
    -- The JobSpec sent to workers, with secrets *sealed* (decrypted only at claim time).
    spec           jsonb NOT NULL,
    worker_id      uuid REFERENCES execution_workers(id) ON DELETE SET NULL,
    lease_until    timestamptz,
    not_before     timestamptz NOT NULL DEFAULT now(),
    cancel_requested boolean NOT NULL DEFAULT false,
    -- true when a later attempt replaced this one (retries keep history).
    superseded     boolean NOT NULL DEFAULT false,
    claimed_at     timestamptz,
    started_at     timestamptz,
    finished_at    timestamptz,
    duration_ms    bigint,
    browser_version text,
    error          text,
    -- Evidence blobs (append-only, read whole).
    logs           jsonb NOT NULL DEFAULT '[]'::jsonb,
    network        jsonb NOT NULL DEFAULT '[]'::jsonb,
    created_at     timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX execution_jobs_exec_idx ON execution_jobs (execution_id);
CREATE INDEX execution_jobs_claim_idx ON execution_jobs (created_at) WHERE status = 'queued';
CREATE INDEX execution_jobs_lease_idx ON execution_jobs (lease_until) WHERE status IN ('claimed','running');
CREATE INDEX execution_jobs_scenario_idx ON execution_jobs (scenario_id, created_at DESC);

CREATE TABLE job_events (
    id           bigserial PRIMARY KEY,
    job_id       uuid NOT NULL REFERENCES execution_jobs(id) ON DELETE CASCADE,
    execution_id uuid NOT NULL REFERENCES test_executions(id) ON DELETE CASCADE,
    kind         text NOT NULL,
    data         jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX job_events_exec_idx ON job_events (execution_id, id);

CREATE TABLE test_artifacts (
    id            uuid PRIMARY KEY,
    execution_id  uuid NOT NULL REFERENCES test_executions(id) ON DELETE CASCADE,
    job_id        uuid NOT NULL REFERENCES execution_jobs(id) ON DELETE CASCADE,
    project_id    uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    name          text NOT NULL,
    kind          text NOT NULL CHECK (kind IN ('screenshot','video','trace','log','console','network','response')),
    content_type  text NOT NULL,
    size_bytes    bigint NOT NULL,
    sha256        text NOT NULL,
    storage_backend text NOT NULL DEFAULT 'local',
    storage_key   text NOT NULL,
    created_at    timestamptz NOT NULL DEFAULT now(),
    UNIQUE (job_id, name)
);
CREATE INDEX test_artifacts_exec_idx ON test_artifacts (execution_id);

CREATE TABLE test_execution_steps (
    id           uuid PRIMARY KEY,
    job_id       uuid NOT NULL REFERENCES execution_jobs(id) ON DELETE CASCADE,
    execution_id uuid NOT NULL REFERENCES test_executions(id) ON DELETE CASCADE,
    position     int NOT NULL,
    keyword      text NOT NULL,
    text         text NOT NULL,
    status       text NOT NULL CHECK (status IN ('passed','failed','skipped','error')),
    started_at   timestamptz NOT NULL,
    duration_ms  bigint NOT NULL,
    message      text,
    expected     text,
    actual       text,
    observation  jsonb,
    artifact_name text
);
CREATE INDEX test_execution_steps_job_idx ON test_execution_steps (job_id, position);

-- ───────────────────────── AI ─────────────────────────
CREATE TABLE ai_providers (
    id                uuid PRIMARY KEY,
    workspace_id      uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    kind              text NOT NULL CHECK (kind IN ('openai','anthropic','gemini','azure_openai','ollama','openai_compatible','mock')),
    name              text NOT NULL,
    base_url          text,
    api_key_encrypted text,
    api_version       text,
    enabled           boolean NOT NULL DEFAULT true,
    is_default        boolean NOT NULL DEFAULT false,
    created_by        uuid REFERENCES users(id),
    created_at        timestamptz NOT NULL DEFAULT now(),
    UNIQUE (workspace_id, name)
);

CREATE TABLE ai_models (
    id                     uuid PRIMARY KEY,
    provider_id            uuid NOT NULL REFERENCES ai_providers(id) ON DELETE CASCADE,
    name                   text NOT NULL,
    context_window         int,
    input_cost_per_mtok    numeric(12,4) NOT NULL DEFAULT 0,
    output_cost_per_mtok   numeric(12,4) NOT NULL DEFAULT 0,
    supports_json          boolean NOT NULL DEFAULT true,
    is_default             boolean NOT NULL DEFAULT false,
    UNIQUE (provider_id, name)
);

CREATE TABLE ai_requests (
    id           uuid PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    project_id   uuid REFERENCES projects(id) ON DELETE SET NULL,
    provider_id  uuid REFERENCES ai_providers(id) ON DELETE SET NULL,
    provider_kind text NOT NULL,
    model        text NOT NULL,
    purpose      text NOT NULL,
    status       text NOT NULL CHECK (status IN ('succeeded','failed')),
    attempts     int NOT NULL DEFAULT 1,
    latency_ms   bigint NOT NULL DEFAULT 0,
    error        text,
    created_by   uuid REFERENCES users(id),
    created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ai_requests_ws_idx ON ai_requests (workspace_id, created_at DESC);

CREATE TABLE ai_usage (
    id            uuid PRIMARY KEY,
    request_id    uuid NOT NULL REFERENCES ai_requests(id) ON DELETE CASCADE,
    workspace_id  uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    input_tokens  int NOT NULL DEFAULT 0,
    output_tokens int NOT NULL DEFAULT 0,
    cost_usd      numeric(14,6) NOT NULL DEFAULT 0,
    created_at    timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE failure_investigations (
    id                    uuid PRIMARY KEY,
    job_id                uuid NOT NULL REFERENCES execution_jobs(id) ON DELETE CASCADE,
    execution_id          uuid NOT NULL REFERENCES test_executions(id) ON DELETE CASCADE,
    project_id            uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    category              text NOT NULL CHECK (category IN ('application_defect','test_defect','environment_failure','dependency_failure','authentication_failure','flaky_test','unknown')),
    deterministic_category text NOT NULL,
    confidence            real NOT NULL,
    summary               text NOT NULL,
    probable_root_cause   text NOT NULL,
    -- Observations: facts extracted from evidence by deterministic code.
    observations          jsonb NOT NULL,
    -- Interpretation: AI output, kept separate and labelled; null without AI.
    interpretation        jsonb,
    suggested_investigation jsonb NOT NULL DEFAULT '[]'::jsonb,
    suggested_remediation jsonb NOT NULL DEFAULT '[]'::jsonb,
    ai_request_id         uuid REFERENCES ai_requests(id) ON DELETE SET NULL,
    created_by            uuid REFERENCES users(id),
    created_at            timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX failure_investigations_job_idx ON failure_investigations (job_id, created_at DESC);

CREATE TABLE ai_recommendations (
    id          uuid PRIMARY KEY,
    project_id  uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    kind        text NOT NULL,
    title       text NOT NULL,
    body        text NOT NULL,
    source      text NOT NULL CHECK (source IN ('ai','heuristic')),
    status      text NOT NULL DEFAULT 'open' CHECK (status IN ('open','accepted','dismissed')),
    related     jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at  timestamptz NOT NULL DEFAULT now()
);

-- ───────────────────────── Governance ─────────────────────────
CREATE TABLE approvals (
    id           uuid PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    project_id   uuid REFERENCES projects(id) ON DELETE CASCADE,
    subject_type text NOT NULL,
    subject_id   uuid NOT NULL,
    status       text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected')),
    requested_by uuid REFERENCES users(id),
    decided_by   uuid REFERENCES users(id),
    decided_at   timestamptz,
    comment      text,
    created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX approvals_subject_idx ON approvals (subject_type, subject_id);

CREATE TABLE audit_events (
    id            bigserial PRIMARY KEY,
    workspace_id  uuid REFERENCES workspaces(id) ON DELETE CASCADE,
    actor_kind    text NOT NULL CHECK (actor_kind IN ('user','api_token','worker','system')),
    actor_id      uuid,
    actor_label   text,
    action        text NOT NULL,
    subject_type  text,
    subject_id    uuid,
    data          jsonb NOT NULL DEFAULT '{}'::jsonb,
    ip            text,
    created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX audit_events_ws_idx ON audit_events (workspace_id, id DESC);

CREATE TABLE integrations (
    id               uuid PRIMARY KEY,
    workspace_id     uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    project_id       uuid REFERENCES projects(id) ON DELETE CASCADE,
    kind             text NOT NULL CHECK (kind IN ('github','gitlab','jira','slack','github_actions','gitlab_ci','webhook')),
    name             text NOT NULL,
    config           jsonb NOT NULL DEFAULT '{}'::jsonb,
    secret_encrypted text,
    events           text[] NOT NULL DEFAULT '{execution.completed}',
    enabled          boolean NOT NULL DEFAULT true,
    created_by       uuid REFERENCES users(id),
    created_at       timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE integration_deliveries (
    id             uuid PRIMARY KEY,
    integration_id uuid NOT NULL REFERENCES integrations(id) ON DELETE CASCADE,
    event          text NOT NULL,
    status_code    int,
    error          text,
    duration_ms    bigint,
    created_at     timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX integration_deliveries_idx ON integration_deliveries (integration_id, created_at DESC);

CREATE TABLE recordings (
    id                  uuid PRIMARY KEY,
    project_id          uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    runner_recording_id text,
    url                 text NOT NULL,
    status              text NOT NULL DEFAULT 'recording' CHECK (status IN ('recording','stopped','converted','failed')),
    events              jsonb NOT NULL DEFAULT '[]'::jsonb,
    created_by          uuid REFERENCES users(id),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now()
);

